#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/merge.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="The merge both git:merge:* tasks run"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# The Python form of the shell library merge. It has the same function, the
# same landing modes, the same git commands in the same order, the same output
# and the same exit codes.
#
# A task imports it after the import preamble, which puts
# ${MISE_PROJECT_ROOT}/.config/mise/tasks/_scripts on sys.path:
#
#   import merge
#   merge.merge_to_destination_branch("main", source)
#
# One function, two entrypoints. git:merge:develop and git:merge:main use
# different branch names only. This module keeps the sequence, so that the two
# merges stay the same.
#
# The branch model comes from core_branches of .config/bootstrap/repo.toml:
#
#   - main and develop: work starts on feature branches, goes into develop, and
#     goes into main only by a merge. The tasks are git:merge:develop and
#     git:merge:main.
#   - only one of them: each feature branch merges into that branch. The task
#     is git:merge:<branch> of that branch.
#
# The sync writes the task of each core branch, and removes the others.
#
# The merge config is in the values. Each repository reads the table
# [branches.<destination>] of its own .config/bootstrap/repo.toml with
# bootstrap config get, also the root of a repository with submodules and each
# submodule. The table has landing, and one of merge_from (the only branches
# that can merge in) and merge_never (the branches that never merge in).
# Without the two lists, the defaults are the branch model: into main with
# develop, only from develop; into a different destination, never from main.
# A feature branch that did not go through develop did not go through the
# branch that the pipeline builds, and nobody writes work on main.
#
# When core_branches has main and develop, a direct landing of develop on main
# is a fast-forward (--ff-only). main only
# moves forward to a commit of develop, so main is always an ancestor of
# develop, and main is the same commit that develop tested. A merge commit on
# main would put main ahead of develop with commits that change no file. The
# tags record the releases. Before it changes a branch, the merge makes sure
# that main, local and on origin, is an ancestor of develop. If not, it stops
# with the fix: merge main into develop first. It never falls back to --no-ff.
#
# Each other direct landing uses --no-ff on purpose: the merge commit records
# which commits of a feature branch landed, and git revert -m 1 removes them.
#
# The landing sets HOW the source gets to the destination, never WHETHER. Each
# destination has its own landing. The branch rules above apply to each value,
# and each check below runs for each value:
#
#   direct-merge   the default: merge locally and push the destination. For a
#                  solo repository, or one with the review before the branch
#                  lands. Without an origin remote, it merges locally and does
#                  not pull or push. It makes no commit on the branch itself.
#   direct-commit  the same merge. A commit on the branch itself is also
#                  permitted (the no-commit-to-branch hook does not protect the
#                  branch).
#   pr             push the branch and open a pull request against the
#                  destination. Nothing merges locally; the forge merges.
#
# The repository makes the choice. This module names a forge only when it opens
# a request.
#
# A failed command stops the merge with the code that the shell version gives:
# exit 1 after the error lines, or the code of the command where the shell
# stops on set -e.

import os
import shutil
import subprocess
import sys

import checks
import helpers


def _git_out(*args):
  """Runs git and returns its stdout without the trailing line breaks.

  When git fails, the task stops with the code of git, as a command
  substitution under set -e does. The stderr of git stays on the screen.
  """
  result = subprocess.run(["git", *args], check=False, stdout=subprocess.PIPE, text=True)
  if result.returncode != 0:
    sys.exit(result.returncode)
  return result.stdout.rstrip("\n")


def _git_quiet(*args):
  """Runs git with no output and returns True when git exits 0."""
  result = subprocess.run(["git", *args], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
  return result.returncode == 0


def require_own_repository():
  """Stops the task when mise runs it for a different repository.

  In a submodule, mise also finds the tasks of the root repository. If the
  submodule has no merge task of that name, mise runs the task of the root in
  the root folder, and that task then lands a branch of the root.
  MISE_ORIGINAL_CWD is the folder of the shell. With `mise run --cd <folder>`
  or `mise -C <folder>`, it is not <folder>, and no variable gives <folder>.
  Thus the task stops only when the folder of the shell is inside the tree of
  the repository of the task, but in another git repository: a submodule or a
  nested repository. A run from a subfolder of the same repository passes, and
  so does a run from a folder outside the tree, for example
  `mise run --cd <repo>` from a parent folder.
  """
  original = os.environ.get("MISE_ORIGINAL_CWD", "")
  if not original:
    return
  result = subprocess.run(
    ["git", "-C", original, "rev-parse", "--show-toplevel"],
    check=False,
    stdout=subprocess.PIPE,
    stderr=subprocess.DEVNULL,
    text=True,
  )
  if result.returncode != 0:
    return
  here = result.stdout.rstrip("\n")
  result = subprocess.run(
    ["git", "-C", os.environ["MISE_PROJECT_ROOT"], "rev-parse", "--show-toplevel"],
    check=False,
    stdout=subprocess.PIPE,
    stderr=subprocess.DEVNULL,
    text=True,
  )
  there = result.stdout.rstrip("\n") if result.returncode == 0 else ""
  inside = there and os.path.commonpath([os.path.realpath(here), os.path.realpath(there)]) == os.path.realpath(there)
  if here != there and inside:
    task = os.environ.get("MISE_TASK_NAME") or "this task"
    such = os.environ.get("MISE_TASK_NAME") or "such task"
    helpers.print_error(f"{task} is a task of {there}, not of {here}.")
    helpers.print_warn(f"- {here} has no {such}, so mise found the task of the repository above it")
    helpers.print_warn(f"- run `mise run setup:configs` in {here} for its own merge tasks, then merge again")
    sys.exit(1)


# The shell version runs this check when a task sources the library, so this
# module runs it when a task imports it.
require_own_repository()


def precommit_safety_net():
  """The gate that each merge passes before it changes a branch.

  It runs the hooks over the FULL tree, and it fails if a hook changed a file.

  This is a safety net, not the work gate. A person runs code:precommit before
  staging, so each fix goes into the commit that caused it. When a merge runs,
  a hook that still finds a problem means that a commit went in without the
  hooks. The merge stops here. It does not commit the fix, and it does not
  amend a commit of a different person. Thus the repair stays on the branch
  that needs it, and the output names the files.
  """
  config = f"{os.environ['MISE_PROJECT_ROOT']}/.config/pre-commit-config.yaml"

  if not os.path.isfile(config):
    helpers.print_warn("No .config/pre-commit-config.yaml — skipping the hook safety net.")
    return
  if shutil.which("pre-commit") is None:
    helpers.print_warn("pre-commit is not on PATH — skipping the hook safety net.")
    helpers.print_yellow("Run `mise run setup` to install the dev toolchain.")
    return

  helpers.print_wait("Running the hooks over every file ... ")
  # no-commit-to-branch protects a commit, and the safety net makes no commit.
  # The net skips it, because a merge can run from a branch that the hook
  # protects, for example git:merge:main from develop. The net keeps a SKIP
  # that the caller set.
  env = dict(os.environ)
  skip = env.get("SKIP", "")
  env["SKIP"] = f"{skip},no-commit-to-branch" if skip else "no-commit-to-branch"
  result = subprocess.run(
    ["pre-commit", "run", "--config", config, "--all-files"],
    check=False,
    env=env,
    stdout=subprocess.DEVNULL,
    stderr=subprocess.DEVNULL,
  )
  hooks_passed = result.returncode == 0

  # A code other than 0 has two meanings: a hook failed, or a format hook
  # changed a file and gave the change as a failure. The code does not show
  # which. The working tree shows it: the checks before this refused a dirty
  # tree, so a dirty tree NOW has changes from a hook. That is the usual case,
  # and the output lists the files. Changes inside a submodule are skipped,
  # for the reason that has_uncommitted_changes gives.
  dirty = _git_out("status", "--porcelain", "--ignore-submodules=dirty")
  if dirty:
    helpers.print_error()
    helpers.print_error("- The hooks rewrote files, so this branch was committed without them:")
    for line in dirty.split("\n"):
      if line:
        helpers.print_warn(f"  {line}")
    helpers.print_error("- Commit the fixes on this branch, then merge again.")
    sys.exit(1)

  if not hooks_passed:
    helpers.print_error()
    helpers.print_error("- A hook failed without changing anything, so it needs a fix by hand.")
    helpers.print_error("- Run `mise run code:precommit --all` to see it.")
    sys.exit(1)
  helpers.print_success()


def open_pull_request(destination_branch, source_branch):
  """The pr part of the merge model: push the branch and let the forge merge it.

  It checks out nothing and merges no branch, so the move to the main worktree
  of the direct path does not apply. The one local change is the upstream of
  the source branch.
  """
  helpers.print_wait(f"Pushing {source_branch} to origin ... ")
  if not _git_quiet("push", "--follow-tags", "-u", "origin", source_branch):
    helpers.print_error()
    helpers.print_error(f"FAILED to push '{source_branch}' to origin!")
    sys.exit(1)
  helpers.print_success()

  # gh comes first when both are installed. Two forge CLIs on one machine is
  # usually a GitHub repository on a laptop that also has glab, and the request
  # goes to ONE forge.
  if helpers.has_tool("gh"):
    helpers.print_yellow(f"Opening a pull request into {destination_branch} ...")
    result = helpers.tool("gh", "pr", "create", "--base", destination_branch, "--head", source_branch, "--fill")
    if result.returncode != 0:
      sys.exit(result.returncode)
  elif helpers.has_tool("glab"):
    helpers.print_yellow(f"Opening a merge request into {destination_branch} ...")
    result = helpers.tool(
      "glab",
      "mr",
      "create",
      "--target-branch",
      destination_branch,
      "--source-branch",
      source_branch,
      "--fill",
    )
    if result.returncode != 0:
      sys.exit(result.returncode)
  else:
    # This is not a failure. The branch is on origin, which is the part that
    # needs a shell. To open the request is one click, and a machine whose
    # forge has no CLI usually has no forge CLI on PATH.
    helpers.print_warn("No forge CLI on PATH — the branch is pushed, no request was opened.")
    helpers.print_yellow(f"  branch:      {source_branch}")
    helpers.print_yellow(f"  destination: {destination_branch}")
    helpers.print_yellow("Open the pull request on your forge.")

  helpers.print_newline()
  helpers.print_success("Branch pushed — the merge happens on the forge.")


def require_fast_forward(destination_branch, source_branch, has_origin):
  """Stops the merge when destination_branch cannot fast-forward to source_branch.

  It runs before the merge changes a branch. The local destination, when it
  exists, and the destination of origin must each be an ancestor of the
  source. The fetch first gets the destination of origin, because the pull
  after the checkout gets it too, and a commit there that the source does not
  have makes the fast-forward fail after the checkout. The fetch changes no
  local branch.
  """
  helpers.print_wait(f"Checking if {destination_branch} can fast-forward to {source_branch} ... ")
  refs = []
  if _git_quiet("show-ref", "--verify", "--quiet", f"refs/heads/{destination_branch}"):
    refs.append(destination_branch)
  if has_origin:
    if not _git_quiet("fetch", "--quiet", "origin", destination_branch):
      helpers.print_error()
      helpers.print_error(f"FAILED to fetch '{destination_branch}' from origin!")
      sys.exit(1)
    refs.append(f"origin/{destination_branch}")

  for ref in refs:
    if _git_quiet("merge-base", "--is-ancestor", ref, source_branch):
      continue
    count = _git_out("rev-list", "--count", f"{source_branch}..{ref}")
    helpers.print_error()
    helpers.print_error(
      f"{ref} has {count} commit(s) that {source_branch} does not have, "
      f"so {destination_branch} cannot fast-forward to {source_branch}."
    )
    for line in _git_out("log", "--oneline", "-n", "10", f"{source_branch}..{ref}").split("\n"):
      helpers.print_warn(f"  {line}")
    helpers.print_warn(
      f"- merge {ref} into {source_branch} (`git switch {source_branch} && git merge {ref}`),"
      f" push {source_branch}, then land again"
    )
    sys.exit(1)
  helpers.print_success()


def read_merge_config(destination_branch):
  """Returns (landing, merge_mode, merge_from, merge_never) for a destination.

  landing is pr, direct-merge or direct-commit. merge_mode is pr, else direct.
  merge_from and merge_never are lists of branch names. The values come from
  [branches.<destination>] of .config/bootstrap/repo.toml, read with
  bootstrap config get. Without the table or a key, the defaults of the branch
  model apply. It stops when the table sets the two lists, or when it cannot
  read the values: a branch rule that it cannot read must not become "each
  branch".
  """
  # The branch segment has double quotes, so a branch name with "." is one key.
  table = helpers.bootstrap_get(f'repo.branches."{destination_branch}"')
  value = table.get("value")
  if value is None:
    value = {}
  landing = value.get("landing") if isinstance(value, dict) else None
  merge_from = value.get("merge_from") if isinstance(value, dict) else None
  merge_never = value.get("merge_never") if isinstance(value, dict) else None
  if (
    not isinstance(value, dict)
    or not isinstance(landing, (str, type(None)))
    or not isinstance(merge_from, (list, type(None)))
    or not isinstance(merge_never, (list, type(None)))
  ):
    helpers.print_error(f"cannot read [branches.{destination_branch}] of .config/bootstrap/repo.toml.")
    sys.exit(1)
  has_from = "merge_from" in value
  has_never = "merge_never" in value
  if landing is None:
    landing = "direct-merge"
  merge_from = list(merge_from or [])
  merge_never = list(merge_never or [])

  if has_from and has_never:
    helpers.print_error(f"[branches.{destination_branch}] sets both merge_from and merge_never.")
    helpers.print_warn("- keep one of them in .config/bootstrap/repo.toml")
    sys.exit(1)
  if not has_from and not has_never:
    if destination_branch == "main" and checks.branch_exists("develop"):
      merge_from = ["develop"]
    else:
      merge_never = ["main"]

  # direct-merge and direct-commit both merge here; only pr opens a request.
  # The schema of bootstrap config permits no other value.
  merge_mode = "pr" if landing == "pr" else "direct"
  return landing, merge_mode, merge_from, merge_never


def merge_to_destination_branch(destination_branch, source_branch=None):
  """Lands source_branch on destination_branch.

  source_branch is the current branch by default, which is the default of
  git:merge:develop. git:merge:main names develop when it is a core branch.
  """
  current_branch = _git_out("rev-parse", "--abbrev-ref", "HEAD")
  if not source_branch:
    source_branch = current_branch

  landing, merge_mode, merge_from, merge_never = read_merge_config(destination_branch)

  helpers.print_header(f"Landing {source_branch} on {destination_branch} ({landing}) ...")

  if merge_from and source_branch not in merge_from:
    helpers.print_error(f"merges INTO '{destination_branch}' are only allowed from: {' '.join(merge_from)}")
    helpers.print_warn(f"- the source is '{source_branch}'")
    helpers.print_warn(f"- merge_from of [branches.{destination_branch}] in .config/bootstrap/repo.toml decides this")
    sys.exit(1)
  if merge_never and source_branch in merge_never:
    helpers.print_error(f"merges FROM '{source_branch}' into '{destination_branch}' are not allowed.")
    helpers.print_warn(f"- merge_never of [branches.{destination_branch}] in .config/bootstrap/repo.toml decides this")
    sys.exit(1)

  if source_branch == destination_branch:
    helpers.print_error(f"'{source_branch}' cannot be merged into itself.")
    sys.exit(1)

  if current_branch == destination_branch:
    helpers.print_error(f"you are already on '{destination_branch}'.")
    helpers.print_warn("- run this from the branch being merged, so it is the one that is checked")
    sys.exit(1)

  # A repository without origin has nothing to pull from or push to. direct
  # still merges locally. pr cannot open a request, so it stops before the
  # hook pass, not after it.
  has_origin = _git_quiet("remote", "get-url", "origin")
  if merge_mode == "pr" and not has_origin:
    helpers.print_error(
      f'landing "pr" of [branches.{destination_branch}] needs an origin remote, and this repository has none.'
    )
    helpers.print_warn("- add one (`git remote add origin <url>`), or run")
    helpers.print_warn(f"  `bootstrap config set 'repo.branches.\"{destination_branch}\".landing' direct-merge`")
    sys.exit(1)

  # The destination must EXIST. This check finds that now, not at the checkout
  # below. Else the run passes each check above, runs the hook pass over the
  # full tree, moves to the main worktree, and only then fails on git checkout,
  # after minutes, with a fact that one command can find.
  if not checks.branch_exists(destination_branch):
    helpers.print_error(f"branch '{destination_branch}' does not exist here or on origin.")
    helpers.print_warn(f"- create it (`git branch {destination_branch}`), then run")
    helpers.print_warn("  `mise run setup:configs` so the merge tasks match the branches")
    sys.exit(1)

  # A branch that a linked worktree has checked out cannot be checked out in a
  # different worktree, so the checkout below occurs in the main worktree. The
  # end state is different for each case: from a linked worktree, the main
  # worktree goes back to its branch; from the main worktree, the run goes back
  # to the branch where the merge started.
  is_worktree = False
  main_worktree_path = ""
  restore_branch = ""
  original_dir = os.getcwd()

  if checks.is_git_worktree():
    is_worktree = True
    main_worktree_path = checks.get_main_worktree_path()
    main_worktree_branch = _git_out("-C", main_worktree_path, "rev-parse", "--abbrev-ref", "HEAD")
    if main_worktree_branch != destination_branch:
      restore_branch = main_worktree_branch
  else:
    restore_branch = current_branch

  helpers.print_wait("Checking if any untracked files exist ... ")
  if checks.has_untracked_files():
    helpers.print_error()
    helpers.print_error("- Untracked files exist, please commit or remove them and try again.")
    sys.exit(1)
  helpers.print_success()

  helpers.print_wait("Checking if any uncommitted changes exist ... ")
  if checks.has_uncommitted_changes():
    helpers.print_error()
    helpers.print_error("- Uncommitted changes exist, please commit or remove them and try again.")
    sys.exit(1)
  helpers.print_success()

  # The merge refuses unpushed work. It does not push it. The merge is about to
  # publish the commits of this branch into the destination, and the pipeline
  # never built a commit that the remote does not have. The check examines only
  # the SOURCE branch: unpushed work on a different local branch is not a
  # concern of this merge.
  #
  # Under pr the check does not apply: the FIRST step of that path pushes the
  # source branch, so the check would refuse the usual case, a branch with a
  # new commit that is not on a remote yet.
  if merge_mode == "direct":
    helpers.print_wait(f"Checking if any unpushed commits exist on {source_branch} ... ")
    if checks.is_local_branch(source_branch):
      helpers.print_yellow("local branch")
    elif checks.has_unpushed_commits(source_branch):
      helpers.print_error()
      helpers.print_error(f"- Unpushed commits exist on '{source_branch}', please push them and try again.")
      sys.exit(1)
    else:
      helpers.print_success()

  # develop lands on main with a fast-forward, but only when develop is a core
  # branch. In a repository with only main, a feature branch with the name
  # develop is a feature branch, and it gets the merge commit. The check runs
  # here, before the hook pass and before a branch changes, so a refusal
  # changes nothing.
  fast_forward = merge_mode == "direct" and destination_branch == "main" and source_branch == "develop"
  if fast_forward:
    core = helpers.bootstrap_get("repo.core_branches").get("value")
    if not isinstance(core, (list, type(None))):
      helpers.print_error("cannot read core_branches of .config/bootstrap/repo.toml.")
      sys.exit(1)
    fast_forward = "develop" in (core or [])
  if fast_forward:
    require_fast_forward(destination_branch, source_branch, has_origin)

  precommit_safety_net()

  # The fork. The steps above are the policy of the two models; the steps below
  # are the local merge, which only direct does.
  if merge_mode == "pr":
    open_pull_request(destination_branch, source_branch)
    return

  if is_worktree:
    helpers.print_wait(f"Switching to main worktree at {main_worktree_path} ... ")
    try:
      os.chdir(main_worktree_path)
    except OSError:
      helpers.print_error()
      helpers.print_error(f"FAILED to switch to main worktree at '{main_worktree_path}'!")
      sys.exit(1)
    helpers.print_success()

  helpers.print_wait(f"Checkout {destination_branch} branch ... ")
  if not _git_quiet("checkout", destination_branch):
    helpers.print_error()
    helpers.print_error(f"FAILED to checkout '{destination_branch}' branch!")
    sys.exit(1)
  helpers.print_success()

  # The pull also gets the tags, because releases are cut on main, and an old
  # tag list can cause a version to be used again.
  if has_origin:
    helpers.print_wait(f"Pulling latest changes from {destination_branch} branch ... ")
    if not _git_quiet("pull", "origin", destination_branch, "--tags"):
      if restore_branch:
        _git_quiet("checkout", restore_branch, "-q")
      helpers.print_error()
      helpers.print_error(f"FAILED to pull latest changes from '{destination_branch}' branch!")
      sys.exit(1)
    helpers.print_success()

  if fast_forward:
    # require_fast_forward made sure that this works. If a commit got onto the
    # destination after that check, git refuses the fast-forward before it
    # changes a file, so the run restores the branch and stops.
    helpers.print_wait(f"Fast-forwarding {destination_branch} to {source_branch} ... ")
    if not _git_quiet("merge", "--ff-only", source_branch):
      if restore_branch:
        _git_quiet("checkout", restore_branch, "-q")
      helpers.print_error()
      helpers.print_error(f"FAILED to fast-forward {destination_branch} to {source_branch}!")
      helpers.print_warn(f"- merge {destination_branch} into {source_branch}, push {source_branch}, then land again")
      sys.exit(1)
    helpers.print_success()
  else:
    # A conflict stops here, and the tree stays in the merge on purpose. An
    # abort removes the one useful fact, which files do not agree, and only a
    # person can resolve the conflict.
    helpers.print_wait(f"Merging {source_branch} into {destination_branch} ... ")
    if not _git_quiet("merge", "--no-ff", "--no-edit", source_branch):
      helpers.print_error()
      helpers.print_error(f"FAILED to merge {source_branch} into {destination_branch}!")
      helpers.print_warn("- the tree is left mid-merge; resolve the conflicts and commit,")
      helpers.print_warn("  or run `git merge --abort` to undo it")
      sys.exit(1)
    helpers.print_success()

  if has_origin:
    helpers.print_wait(f"Pushing {destination_branch} branch to origin ... ")
    if not _git_quiet("push", "origin", destination_branch, "--follow-tags"):
      helpers.print_error()
      helpers.print_error(f"FAILED to push {destination_branch} branch to origin!")
      sys.exit(1)
    helpers.print_success()
  else:
    helpers.print_warn("No origin remote — the merge stays local, nothing was pushed.")

  if restore_branch:
    if is_worktree:
      helpers.print_wait(f"Restoring main worktree to {restore_branch} branch ... ")
    else:
      helpers.print_wait(f"Checkout back to {restore_branch} branch ... ")
    if not _git_quiet("checkout", restore_branch):
      helpers.print_error()
      helpers.print_error(f"FAILED to checkout back to '{restore_branch}' branch!")
      sys.exit(1)
    helpers.print_success()

  try:
    os.chdir(original_dir)
  except OSError:
    pass

  helpers.print_newline()
  helpers.print_success("Merge completed successfully!")
